head.script:
scwin.onpageload = function() {
		var jsonData = [{
			"label" : "label1",
			"value" : "value1",
			"depth" : 1,
			"folder" : "false"
		}, {
			"label" : "label2",
			"value" : "value2",
			"depth" : 1,
			"folder" : "true"
		}, {
			"label" : "label3",
			"value" : "value3",
			"depth" : 2,
			"folder" : "true"
		}, {
			"label" : "label4",
			"value" : "value4",
			"depth" : 3,
			"folder" : "true"
		}, {
			"label" : "label5b",
			"value" : "value5b",
			"depth" : 5,
			"folder" : "true"
		}, {
			"label" : "label5",
			"value" : "value5",
			"depth" : 2,
			"folder" : "false"
		}, {
			"label" : "label6",
			"value" : "value6",
			"depth" : 1,
			"folder" : "false"
		}];
		dataList1.setJSON(jsonData);
};
scwin.trigger1_onclick = function(e) {
	var selectedValue = treeView1.getSelectedValue();
	window.chk_childData1 = treeView1.getChildData(selectedValue);
};
scwin.trigger2_onclick = function(e) {
	var selectedValue = treeView1.getSelectedValue();
	window.chk_childData2 = treeView1.getChildData(selectedValue, true);
};
scwin.trigger3_onclick = function(e) {
	var selectedValue = treeView1.getSelectedValue();
	window.chk_childNodes3 = treeView1.getChildNodes(selectedValue);
};
scwin.trigger4_onclick = function(e) {
	var selectedValue = treeView1.getSelectedValue();
	window.chk_childNodes4 = treeView1.getChildNodes(selectedValue, true);
};
scwin.checkVal1 = function() {
	return window.chk_childNodes3.length == 4;
};
scwin.checkVal2 = function() {
	return window.chk_childNodes4.length == 7;
};
